  "ht_readmeTitle": "Looking for technical details?",
  "ht_readmeDesc": "This FAQ keeps things simple for daily teaching. If you need file paths, data formats, architecture notes, or developer details, check the technical README.md file.",
  "ht_openReadme": "Open README.md",
  "ht_revealReadme": "Show in folder",
